<?php
require dirname(__DIR__).'/app/core.php';check_csrf();$path=trim(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH),'/');$base=trim(parse_url($_ENV['APP_URL']??'',PHP_URL_PATH),'/');if($base&&str_starts_with($path,$base))$path=trim(substr($path,strlen($base)),'/');$method=$_SERVER['REQUEST_METHOD'];
if($path==='register'&&$method==='POST'){$name=trim($_POST['name']??'');$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$pw=$_POST['password']??'';if(!$name||!$email||strlen($pw)<8){msg('Valid details and 8+ character password required');go('register');}try{$s=db()->prepare('INSERT INTO users(name,email,password) VALUES(?,?,?)');$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);$_SESSION['user']=['id'=>db()->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'customer'];go();}catch(Throwable $e){msg('Email already registered');go('register');}}
if($path==='login'&&$method==='POST'){$s=db()->prepare('SELECT id,name,email,password,role FROM users WHERE email=?');$s->execute([trim($_POST['email']??'')]);$u=$s->fetch();if($u&&password_verify($_POST['password']??'',$u['password'])){session_regenerate_id(true);unset($u['password']);$_SESSION['user']=$u;go();}msg('Incorrect email or password');go('login');}
if($path==='logout'&&$method==='POST'){$_SESSION=[];session_regenerate_id(true);go();}
if($path==='cart/add'&&$method==='POST'){$id=(int)($_POST['id']??0);$s=db()->prepare('SELECT stock FROM products WHERE id=? AND is_active=1');$s->execute([$id]);$p=$s->fetch();if($p&&$p['stock']>0)$_SESSION['cart'][$id]=min($p['stock'],($_SESSION['cart'][$id]??0)+1);go();}
if($path==='checkout'&&$method==='POST'){login_required();$cart=$_SESSION['cart']??[];if(!$cart)go('cart');db()->beginTransaction();try{$ids=array_keys($cart);$s=db()->prepare('SELECT * FROM products WHERE id IN('.implode(',',array_fill(0,count($ids),'?')).') AND is_active=1 FOR UPDATE');$s->execute($ids);$ps=$s->fetchAll();if(count($ps)!==count($ids))throw new Exception('Cart contains unavailable products');$sub=0;foreach($ps as $p){if($p['stock']<$cart[$p['id']])throw new Exception('Insufficient stock');$sub+=$p['price']*$cart[$p['id']];}$shipping=60;$no='ORD-'.date('ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$s=db()->prepare('INSERT INTO orders(user_id,order_number,customer_name,phone,address,subtotal,shipping,total) VALUES(?,?,?,?,?,?,?,?)');$s->execute([user()['id'], $no,trim($_POST['name']??user()['name']),trim($_POST['phone']??''),trim($_POST['address']??''),$sub,$shipping,$sub+$shipping]);$oid=db()->lastInsertId();foreach($ps as $p){$q=$cart[$p['id']];db()->prepare('INSERT INTO order_items(order_id,product_id,product_name,quantity,unit_price) VALUES(?,?,?,?,?)')->execute([$oid,$p['id'],$p['name'],$q,$p['price']]);db()->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$q,$p['id']]);}db()->commit();unset($_SESSION['cart']);msg('Order placed: '.$no);go('orders');}catch(Throwable $e){db()->rollBack();msg($e->getMessage());go('cart');}}
if(str_starts_with($path,'admin')){admin_required();if($path==='admin/product'&&$method==='POST'){$n=trim($_POST['name']??'');if($n){$slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$n),'-')).'-'.bin2hex(random_bytes(2));db()->prepare('INSERT INTO products(name,slug,price,stock,description) VALUES(?,?,?,?,?)')->execute([$n,$slug,max(0,(float)$_POST['price']),max(0,(int)$_POST['stock']),trim($_POST['description']??'')]);}go('admin');}if($path==='admin/status'&&$method==='POST'){db()->prepare('UPDATE orders SET status=? WHERE id=?')->execute([$_POST['status'],(int)$_POST['id']]);go('admin');}$ps=db()->query('SELECT * FROM products ORDER BY id DESC')->fetchAll();$os=db()->query('SELECT o.*,u.email FROM orders o JOIN users u ON u.id=o.user_id ORDER BY o.id DESC LIMIT 40')->fetchAll();$sales=db()->query(\"SELECT COALESCE(SUM(total),0) FROM orders WHERE status!='cancelled'\")->fetchColumn();require ROOT.'/views/admin.php';exit;}
if($path==='orders'){login_required();$s=db()->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$s->execute([user()['id']]);$orders=$s->fetchAll();require ROOT.'/views/orders.php';exit;}
if(in_array($path,['login','register'],true)){$register=$path==='register';require ROOT.'/views/auth.php';exit;}
$cart=$_SESSION['cart']??[];$items=[];$subtotal=0;if($path==='cart'){foreach($cart as $id=>$qty){$s=db()->prepare('SELECT * FROM products WHERE id=?');$s->execute([$id]);if($p=$s->fetch()){$p['qty']=$qty;$p['line']=$p['price']*$qty;$subtotal+=$p['line'];$items[]=$p;}}require ROOT.'/views/cart.php';exit;}
$ps=products(trim($_GET['q']??''));$categories=db()->query('SELECT * FROM categories ORDER BY name')->fetchAll();require ROOT.'/views/home.php';
